  function writeModal(ctx, sec, retry) {
    const st = ctx.state; const isNew = !sec;
    const kv = sec ? Object.keys(sec.keys).map((k) => [k, '']) : [['', '']];
    ctx.modal({ title: isNew ? 'New secret' : 'Write version ' + (sec.currentVersion + 1) + ' of ' + esc(sec.path), cls: 'wide',
      body: (isNew ? UI.field('Path', UI.input('kv/', { attrs: 'data-wpath' }), '1 to 16 segments of lower-case letters, digits, . - _') : '') + '<div class="eyebrow">Values</div><div class="vstack gap6" data-wrows>' + kv.map((p) => row(p[0], p[1])).join('') + '</div><div>' + UI.btn('Add key', { kind: 'ghost', size: 'xs', icon: 'plus', attrs: 'data-waddrow' }) + '</div><div class="formgrid" style="--cols:3">' + UI.field('Check-and-set (cas)', UI.input(isNew ? '0' : retry ? String(sec.currentVersion) : (sec.casRequired ? String(sec.currentVersion) : ''), { type: 'number', attrs: 'data-wcas', placeholder: 'optional' }), isNew ? '0: only when the path is new' : sec.casRequired ? 'Required on this path' : 'Optional') + UI.field('Label', UI.select(['public', 'internal', 'confidential'], sec ? sec.label : 'internal', 'data-wlabel' + (isNew ? '' : ' disabled')), isNew ? 'Applies when the path is created' : 'Set when the path was created') + '</div>' + UI.notice('1 to 200 string values, 64 KiB in all, sealed with the tenant data key (associated data: the version row id). Audited as vault.secret.written without values.', 'info'),
      actions: UI.btn('Cancel', { attrs: 'data-close' }) + UI.btn(isNew ? 'Create' : 'Write', { kind: 'primary', attrs: 'data-wsave' }),
      onMount(m) {
        m.querySelector('[data-waddrow]').addEventListener('click', () => { m.querySelector('[data-wrows]').insertAdjacentHTML('beforeend', row('', '')); });
        m.querySelector('[data-wsave]').addEventListener('click', () => {
          const rows = Array.prototype.slice.call(m.querySelectorAll('[data-wrows] .hstack')).map((r) => [r.querySelector('[data-wk]').value.trim(), r.querySelector('[data-wv]').value]).filter((p) => p[0]);
          if (!rows.length) { ctx.toast('A version needs at least one key.', 'warn'); return; }
          const cas = m.querySelector('[data-wcas]').value;
          if (isNew) {
            const path = m.querySelector('[data-wpath]').value.trim();
            if (!/^kv(\/[a-z0-9._-]+){1,15}$/.test(path)) { ctx.toast('Paths are kv/ plus 1 to 15 segments of lower-case letters, digits, dots, hyphens and underscores.', 'warn'); return; }
            if (st.secrets.some((s) => s.path === path)) { ctx.toast('409: ' + esc(path) + ' exists (cas 0 means only when the path is new). Current version ' + st.secrets.find((s) => s.path === path).currentVersion + '.', 'danger', 5000); return; }
            const keys = {}; rows.forEach((p) => { keys[p[0]] = p[1]; });
            st.secrets.push({ path, label: m.querySelector('[data-wlabel]').value, currentVersion: 1, oldestVersion: 1, maxVersions: 10, casRequired: false, customMetadata: {}, createdBy: 'Mara Okafor', createdAt: '19 Sep 2026', updatedAt: 'just now', rotationPeriodDays: null, owner: 'Mara Okafor', keys, versions: [{ version: 1, state: 'active', createdBy: 'Mara Okafor', createdAt: 'just now' }], usedBy: [] });
            st.sel = path; st.query = ''; App.closeOverlay(); ctx.rerender(); ctx.toast(esc(path) + ' created, version 1 (201). Audited vault.secret.written.', 'ok'); return;
          }
          if (sec.casRequired && cas === '') { ctx.toast('This path requires cas: name the version you saw (' + sec.currentVersion + ').', 'warn'); return; }
          if (cas !== '' && +cas !== sec.currentVersion) { App.closeOverlay(); st.cas = { given: +cas, current: sec.currentVersion }; ctx.rerender(); return; }
          sec.currentVersion += 1; sec.updatedAt = 'just now'; sec.rotatedAt = '19 Sep 2026'; sec.overdue = false; if (sec.rotationPeriodDays) sec.rotationDueAt = 'in ' + sec.rotationPeriodDays + ' d';
          const keys = {}; rows.forEach((p) => { keys[p[0]] = p[1] || sec.keys[p[0]] || ''; }); sec.keys = keys;
          sec.versions.unshift({ version: sec.currentVersion, state: 'active', createdBy: 'Mara Okafor', createdAt: 'just now' });
          let removed = 0; while (sec.versions.length > sec.maxVersions) { sec.versions.pop(); removed++; } sec.oldestVersion = sec.versions[sec.versions.length - 1].version;
          delete st.revealed[sec.path]; st.cas = null; App.closeOverlay(); ctx.rerender(); ctx.toast('Version ' + sec.currentVersion + ' written (200)' + (removed ? '; version' + (removed > 1 ? 's' : '') + ' beyond max versions removed' : '') + '. Audited vault.secret.written.', 'ok');
        });
      } });
    function row(k, v) { return '<div class="hstack gap6">' + UI.input(k, { placeholder: 'key', attrs: 'data-wk aria-label="Key"' }) + UI.input(v, { type: 'password', placeholder: k ? 'new value (empty keeps the current one)' : 'value', attrs: 'data-wv aria-label="Value"' }) + '</div>'; }
  }

